const AR_PAT = [[/^Invalid username or password\. (\d+) attempt\(s\) left before lock\.$/, "اسم المستخدم أو كلمة المرور غير صحيحة. تبقّى $1 محاولة قبل القفل."],[/^Too many failed attempts — account locked for (\d+) minutes\.$/, "محاولات فاشلة كثيرة — تم قفل الحساب لمدة $1 دقيقة."],[/^Account locked after (\d+) failed attempts\. Try again in (\d+) min, or ask the System Admin to unlock it\.$/, "الحساب مقفل بعد $1 محاولة فاشلة. حاول بعد $2 دقيقة أو اطلب من مسؤول النظام فتحه."],[/^Password must be at least (\d+) characters\.$/, "يجب أن تكون كلمة المرور $1 أحرف على الأقل."],[/^Line (\d+): enter the amount requested now\.$/, "السطر $1: أدخل المبلغ المطلوب الآن."],[/^Line (\d+): amounts cannot be negative\.$/, "السطر $1: لا يمكن أن تكون المبالغ سالبة."],[/^Line (\d+): requested now is more than what remains due \((.+)\)\.$/, "السطر $1: المطلوب الآن أكثر من المتبقي ($2)."],[/^Line (\d+): month must look like 11\/2026\.$/, "السطر $1: يجب أن يكون الشهر بالشكل 11/2026."],[/^Line (\d+): the principal part must be between 0 and the amount requested\.$/, "السطر $1: يجب أن يكون الأصل بين 0 والمبلغ المطلوب."],[/^Line (\d+): enter the operation number from the contracts register\.$/, "السطر $1: أدخل رقم العملية من سجل العقود."],[/^Line (\d+): separate the principal from the profit — enter the principal part\.$/, "السطر $1: افصل الأصل عن الربح — أدخل جزء الأصل."],[/^Operation (.+) is not in the contracts register\. Finance must register it first\.$/, "العملية $1 غير موجودة في سجل العقود. يجب أن تسجلها المالية أولاً."],[/^Operation (.+) is registered for another financier\.$/, "العملية $1 مسجلة لمموّل آخر."],[/^Operation (.+) is registered in (\w+), not (\w+)\.$/, "العملية $1 مسجلة بعملة $2 وليس $3."],[/^Operation (.+): principal requested (.+) is more than the remaining principal (.+)\.$/, "العملية $1: الأصل المطلوب $2 أكثر من الأصل المتبقي $3."],[/^Operation (.+) is already registered\.$/, "العملية $1 مسجلة مسبقاً."],[/^(.+) has no active bank account in (\w+)\. Ask the CFO to add one, or choose another payment currency\.$/, "ليس لدى $1 حساب بنكي نشط بعملة $2. اطلب من المدير المالي إضافته أو اختر عملة دفع أخرى."],[/^(.+) already requests operation (.+), instalment (\d+) for this beneficiary\. Submit anyway\?$/, "الطلب $1 يطلب مسبقاً العملية $2، القسط $3 لهذا المستفيد. إرسال على أي حال؟"],[/^(\S+) is no longer waiting for the CFO\. The screen will refresh\.$/, "$1 لم يعد بانتظار المدير المالي. سيتم تحديث الشاشة."],[/^(\S+) is not waiting for a second approval\.$/, "$1 لا ينتظر موافقة ثانية."],[/^(\S+) is not waiting to be issued\.$/, "$1 لا ينتظر الإصدار."],[/^(\S+) is no longer waiting for approval\.$/, "$1 لم يعد بانتظار الموافقة."],[/^There is no exchange rate on or before the document date \((.+)\)\. Finance must enter it first\.$/, "لا يوجد سعر صرف في تاريخ المستند ($1) أو قبله. يجب أن تُدخله المالية أولاً."],[/^It can be cleared or returned from the due date \((.+)\)\.$/, "يمكن التحصيل أو الارتداد من تاريخ الاستحقاق ($1)."],[/^Choose an account in (\w+), the payment currency\.$/, "اختر حساباً بعملة $1، عملة الدفع."],[/^Number (\S+) is not in any chequebook of this account\.$/, "الرقم $1 ليس ضمن أي دفتر لهذا الحساب."],[/^Number (\S+) was voided for this account\.$/, "الرقم $1 ملغى لهذا الحساب."],[/^Number (\S+) is already used on this account\.$/, "الرقم $1 مستخدم مسبقاً في هذا الحساب."],[/^(\S+) is already used by cheques, so it is locked and cannot be changed\.$/, "$1 مستخدم في شيكات، فهو مثبت ولا يمكن تغييره."],[/^(SDG|QAR) moved ([\d.]+)% from ([\d.,]+) on (\S+), more than the ([\d.]+)% alert\. Check the figure, then confirm\.$/, "تغير $1 بنسبة $2% عن $3 في $4، أكثر من تنبيه $5%. تحقق من الرقم ثم أكّد."],[/^Principal cannot be less than what was already requested \((.+)\)\.$/, "لا يمكن أن يقل الأصل عن المطلوب مسبقاً ($1)."],[/^(.+): only PDF, JPG, PNG or WEBP files\.$/, "$1: ملفات PDF أو JPG أو PNG أو WEBP فقط."],[/^(.+) is larger than 10 MB\.$/, "$1 أكبر من 10 ميجابايت."]];
/** Server messages: exact text first, then the patterns with values. */
function tErr(m) {
  if (!m || typeof LANG === 'undefined' || LANG !== 'ar') return m;
  if (AR[m]) return AR[m];
  for (const [re, ar] of AR_PAT) { const x = re.exec(m); if (x) return ar.replace(/\$(\d)/g, (_, i) => x[+i]); }
  return m;
}
